// Owned input registration -> actual multipart/JSON HTTP -> actual generated bytes.
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import test from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
import { randomUUID, createHash } from 'node:crypto';
import { deflateSync } from 'node:zlib';
import { createOwnedGenerationMedia } from '../fixtures/asset-generation-provider-fixture.mjs';
const require = createRequire(import.meta.url), { createAssetService } = require('../../src/core/binary/out/modules/generation/service.js');
const root = path.resolve('F:/AI/AgentMake/CyberSoftwares/GameCowork/codelyreversebackup/work/tests/asset-inputs-' + randomUUID()), store = path.join(root, 'runtime'), incoming = path.join(store, 'incoming');
const media = createOwnedGenerationMedia(root), key = 'owned-input-key-' + randomUUID(), sha = bytes => createHash('sha256').update(bytes).digest('hex'), requests = [], sockets = new Set();
let service, peer, baseUrl, registered;
const makeService = () => createAssetService({ root: store, pollIntervalMs: 20, requestTimeoutMs: 3000 });
const query = (kind, data) => service.dispatch('generator/' + kind, data);
function stage(bytes, filename, workspaceKey = 'workspace-a') {
  const inputId = 'i_' + randomUUID(), file = path.join(incoming, inputId + '.bin'); fs.mkdirSync(incoming, { recursive: true }); fs.writeFileSync(file, bytes, { flag: 'wx' });
  return { file, metadata: { inputId, filename, workspaceKey, byteLength: bytes.length, sha256: sha(bytes) } };
}
function register(bytes, filename, workspaceKey) { const staged = stage(bytes, filename, workspaceKey); try { const result = service.registerInput(staged.metadata); assert.equal(fs.existsSync(staged.file), true, 'Native importer still owns cleanup of incoming bytes'); return result.input; } finally { fs.unlinkSync(staged.file); } }
const taskInput = (inputIds, extra = {}) => ({ providerId: 'multipart', kind: 'image', prompt: 'Owned reference generation', workspaceKey: 'workspace-a', inputIds, ...extra });
async function done(taskId) { const deadline = Date.now() + 5000; for (;;) { const { task } = await query('getTask', { taskId }); if (['completed','failed','interrupted'].includes(task.status)) return task; if (Date.now() > deadline) throw Error('Owned reference task deadline'); await new Promise(resolve => setTimeout(resolve, 10)); } }
function provider(id, create) { return { id, name: 'Owned ' + id, baseUrl, kinds: ['image','video','model'], authMode: 'bearer', apiKey: key, model: 'owned-model', adapter: { create, cancel: null } }; }

test.before(async () => {
  peer = http.createServer(async (request, response) => {
    try {
      const chunks = []; for await (const bytes of request) chunks.push(bytes); const bytes = Buffer.concat(chunks), contentType = request.headers['content-type'] || '';
      const record = { route: request.url, contentType, authorized: request.headers.authorization === 'Bearer ' + key, fields: {}, files: [] };
      if (contentType.startsWith('multipart/form-data; boundary=')) {
        const parsed = await new Request('http://127.0.0.1/owned-parser', { method: 'POST', headers: { 'Content-Type': contentType }, body: bytes }).formData();
        for (const [name, value] of parsed.entries()) if (typeof value === 'string') record.fields[name] = value; else { const file = Buffer.from(await value.arrayBuffer()); record.files.push({ name, filename: value.name, mime: value.type, byteLength: file.length, sha256: sha(file) }); }
      } else record.fields = JSON.parse(bytes);
      requests.push(record); const kind = record.fields.kind || 'image', output = media[kind === 'model' ? 'glb' : kind === 'video' ? 'webm' : 'png'];
      response.writeHead(200, { 'Content-Type': 'application/json' }); response.end(JSON.stringify({ status: 'completed', outputs: [{ base64: output.bytes.toString('base64'), mime: output.mimeType }] }));
    } catch (error) { response.writeHead(400, { 'Content-Type': 'application/json' }); response.end(JSON.stringify({ error: error.message })); }
  });
  peer.on('connection', socket => { sockets.add(socket); socket.on('close', () => sockets.delete(socket)); }); await new Promise(resolve => peer.listen(0, '127.0.0.1', resolve)); baseUrl = 'http://127.0.0.1:' + peer.address().port; service = makeService();
  registered = register(media.png.bytes, '参考图.png');
  await query('saveProvider', { provider: provider('multipart', { method: 'POST', path: '/edit', bodyType: 'multipart', bodyTemplate: { kind: '{{kind}}', model: '{{model}}', prompt: '{{prompt}}', options: '{{parameters}}' }, fileFields: [{ name: 'image[]', inputIndex: 'all' }] }) });
  await query('saveProvider', { provider: provider('json-reference', { method: 'POST', path: '/json', bodyTemplate: { kind: '{{kind}}', prompt: '{{prompt}}', image: '{{inputs.0.dataUrl}}', bytes: '{{inputs.0.base64}}', filename: '{{inputs.0.filename}}' } }) });
});
test.after(async () => { await service?.close(); for (const socket of sockets) socket.destroy(); await new Promise(resolve => peer.close(resolve)); });

test('Native registration persists verified immutable input metadata and never publishes filesystem paths', async () => {
  assert.equal(registered.mime, 'image/png'); assert.equal(registered.kind, 'image'); assert.equal(registered.sha256, media.png.sha256);
  assert.equal(registered.filename, '参考图.png'); assert.equal((await query('getInput', { inputId: registered.id, workspaceKey: 'workspace-a' })).input.id, registered.id);
  const list = await query('getInputs', { workspaceKey: 'workspace-a' }); assert.equal(list.inputs.length, 1); assert.equal(JSON.stringify(list).includes(store), false); assert.equal(JSON.stringify(list).includes('_file'), false);
  assert.equal((await query('getInputs', { workspaceKey: 'workspace-b' })).inputs.length, 0);
  await assert.rejects(() => query('getInput', { inputId: registered.id, workspaceKey: 'workspace-b' }), /not found/);
  const pathResult = service.getInputPath(registered.id, 'workspace-a'); assert.equal(sha(fs.readFileSync(pathResult.path)), media.png.sha256); assert.ok(pathResult.path.startsWith(path.join(store, 'inputs') + path.sep));
});

test('Multipart sends actual Unicode-named reference bytes and leaves the HTTP boundary to FormData', async () => {
  const { task: queued } = await query('createTask', taskInput([registered.id], { prompt: 'Owned "prompt"\nline', parameters: { width: 48, transparent: true } })); const task = await done(queued.id); assert.equal(task.status, 'completed', task.error);
  const sent = requests.at(-1); assert.match(sent.contentType, /^multipart\/form-data; boundary=/); assert.equal(sent.authorized, true); assert.equal(sent.fields.prompt.replaceAll('\r\n','\n'), 'Owned "prompt"\nline'); assert.deepEqual(JSON.parse(sent.fields.options), { width: 48, transparent: true });
  assert.deepEqual(sent.files, [{ name: 'image[]', filename: '参考图.png', mime: 'image/png', byteLength: media.png.size, sha256: media.png.sha256 }]);
  assert.equal(task.inputs[0].id, registered.id); assert.equal(task.inputs[0].sha256, media.png.sha256); assert.equal(JSON.stringify(task).includes('_file'), false); assert.equal(JSON.stringify(task).includes('base64'), false);
  await assert.rejects(() => query('deleteInput', { inputId: registered.id, workspaceKey: 'workspace-a' }), /generation history/);
});

test('Typed JSON input variables deliver exact base64/data URLs to the explicitly configured endpoint', async () => {
  const { task: queued } = await query('createTask', taskInput([registered.id], { providerId: 'json-reference' })); const task = await done(queued.id); assert.equal(task.status, 'completed', task.error);
  const sent = requests.at(-1); assert.equal(sent.contentType, 'application/json'); assert.equal(sent.files.length, 0); assert.equal(sent.fields.filename, '参考图.png'); assert.equal(sha(Buffer.from(sent.fields.bytes, 'base64')), media.png.sha256); assert.equal(sent.fields.image, 'data:image/png;base64,' + media.png.bytes.toString('base64'));
});

