test('A real Windows FILE_SHARE_READ preview lock leaves failed deletion fully retryable', { skip: process.platform !== 'win32' }, async () => {
  const input = register(media.png.bytes, 'shared-read.png'), file = service.getInputPath(input.id, 'workspace-a').path, metadata = path.join(store, 'inputs.json'), before = fs.readFileSync(metadata);
  const script = "$reader=[System.IO.File]::Open('" + file.replaceAll("'", "''") + "',[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::Read); [Console]::Out.WriteLine('owned-reader-ready'); [Console]::In.ReadLine() | Out-Null; $reader.Dispose()";
  const child = spawn('powershell', ['-NoProfile', '-NonInteractive', '-EncodedCommand', Buffer.from(script, 'utf16le').toString('base64')], { windowsHide: true, stdio: ['pipe','pipe','pipe'] });
  const exited = new Promise(resolve => child.once('exit', resolve)); let output = '', stderr = '';
  child.stderr.on('data', bytes => { stderr += bytes; });
  try {
    await new Promise((resolve, reject) => { const timer = setTimeout(() => reject(Error('Owned shared reader deadline: ' + stderr)), 10000); child.stdout.on('data', bytes => { output += bytes; if (output.includes('owned-reader-ready')) { clearTimeout(timer); resolve(); } }); child.once('error', error => { clearTimeout(timer); reject(error); }); });
    await assert.rejects(() => query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' }), /EBUSY|EPERM|locked|permission/);
    assert.deepEqual(fs.readFileSync(metadata), before); assert.equal((await query('getInput', { inputId: input.id, workspaceKey: 'workspace-a' })).input.sha256, input.sha256);
    assert.deepEqual(fs.readFileSync(file), media.png.bytes); assert.equal(fs.readdirSync(path.join(store,'inputs')).some(name => name.startsWith('.delete-' + input.id)), false);
  } finally { child.stdin.end('\n'); assert.equal(await exited, 0); }
  assert.equal((await query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' })).deleted, true); assert.equal(fs.existsSync(file), false); assert.equal(Object.hasOwn(JSON.parse(fs.readFileSync(metadata)), input.id), false);
});

test('Metadata persistence failure rolls a staged deletion back to its usable original file', async () => {
  const input = register(media.png.bytes, 'rollback-delete.png'), file = service.getInputPath(input.id, 'workspace-a').path, metadata = path.join(store, 'inputs.json'), alias = path.join(root, 'inputs-delete-rollback-hardlink.json');
  const before = fs.readFileSync(metadata); fs.linkSync(metadata, alias);
  try {
    await assert.rejects(() => query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' }), /Linked/);
    assert.deepEqual(fs.readFileSync(metadata), before); assert.deepEqual(fs.readFileSync(file), media.png.bytes); assert.equal((await query('getInput', { inputId: input.id, workspaceKey: 'workspace-a' })).input.sha256, input.sha256);
    assert.equal(fs.readdirSync(path.join(store,'inputs')).some(name => name.startsWith('.delete-' + input.id)), false);
  } finally { fs.unlinkSync(alias); }
  await service.close(); service = makeService(); assert.equal((await query('getInput', { inputId: input.id, workspaceKey: 'workspace-a' })).input.sha256, input.sha256);
  assert.equal((await query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' })).deleted, true); assert.equal(fs.existsSync(file), false);
});

test('Cleanup failure after metadata commit restores both the input registry and its original file', async () => {
  const input = register(media.png.bytes, 'cleanup-rollback.png'), file = service.getInputPath(input.id, 'workspace-a').path, metadata = path.join(store, 'inputs.json'), before = fs.readFileSync(metadata), unlink = fs.unlinkSync;
  let injected = false;
  fs.unlinkSync = target => {
    if (path.basename(String(target)).startsWith('.delete-' + input.id)) {
      injected = true; assert.equal(Object.hasOwn(JSON.parse(fs.readFileSync(metadata)), input.id), false, 'The fault occurs after the registry commit');
      const error = new Error('Owned injected cleanup EBUSY'); error.code = 'EBUSY'; throw error;
    }
    return unlink(target);
  };
  try { await assert.rejects(() => query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' }), /Owned injected cleanup EBUSY/); }
  finally { fs.unlinkSync = unlink; }
  assert.equal(injected, true); assert.deepEqual(fs.readFileSync(metadata), before); assert.deepEqual(fs.readFileSync(file), media.png.bytes);
  assert.equal((await query('getInput', { inputId: input.id, workspaceKey: 'workspace-a' })).input.sha256, input.sha256);
  assert.equal((await query('deleteInput', { inputId: input.id, workspaceKey: 'workspace-a' })).deleted, true);
});

