test('Five real 13 MiB inputs exceed the combined limit, and duplicate multipart body bytes have a separate request budget', async () => {
  const table = new Uint32Array(256); for (let i = 0; i < 256; i++) { let value = i; for (let bit = 0; bit < 8; bit++) value = value >>> 1 ^ (value & 1 ? 0xedb88320 : 0); table[i] = value; }
  const chunk = (name, data) => { const result = Buffer.alloc(data.length + 12); result.writeUInt32BE(data.length); result.write(name, 4); data.copy(result, 8); let checksum = 0xffffffff; for (let i = 4; i < result.length - 4; i++) checksum = checksum >>> 8 ^ table[(checksum ^ result[i]) & 255]; result.writeUInt32BE((checksum ^ 0xffffffff) >>> 0, result.length - 4); return result; };
  const width = 2048, height = 1700, header = Buffer.alloc(13); header.writeUInt32BE(width); header.writeUInt32BE(height,4); header[8] = 8; header[9] = 6;
  const pixels = Buffer.alloc((width * 4 + 1) * height), bytes = Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('IDAT',deflateSync(pixels,{level:0})),chunk('IEND',Buffer.alloc(0))]); assert.ok(bytes.length * 5 > 64 * 1024 * 1024);
  const inputs = Array.from({ length: 5 }, (_, index) => register(bytes, 'owned-large-' + index + '.png')), before = requests.length;
  await assert.rejects(() => query('createTask', taskInput(inputs.map(input => input.id))), /combined 64 MiB/); assert.equal(requests.length, before);
  await query('saveProvider', { provider: provider('duplicate-files', { method: 'POST', path: '/duplicated-input', bodyType: 'multipart', fileFields: Array.from({ length: 8 }, (_, index) => ({ name: 'image_' + index, inputIndex: 0 })) }) });
  const { task: queued } = await query('createTask', taskInput([inputs[0].id], { providerId: 'duplicate-files' })), task = await done(queued.id);
  assert.equal(task.status, 'failed'); assert.equal(task.mayContinue, false); assert.match(task.error, /multipart body exceeds 96 MiB/); assert.equal(requests.length, before, 'Local body preparation failures must not submit or report an unknown remote outcome');
  await query('saveProvider', { provider: provider('duplicate-json', { method: 'POST', path: '/duplicated-json', bodyTemplate: { a:'{{inputs.0.base64}}', b:'{{inputs.0.base64}}', c:'{{inputs.0.base64}}', d:'{{inputs.0.base64}}', e:'{{inputs.0.base64}}', f:'{{inputs.0.base64}}' } }) });
  const jsonQueued = await query('createTask', taskInput([inputs[1].id], { providerId: 'duplicate-json' })), jsonTask = await done(jsonQueued.task.id);
  assert.equal(jsonTask.status, 'failed'); assert.equal(jsonTask.mayContinue, false); assert.match(jsonTask.error, /request body exceeds/); assert.equal(requests.length, before);
});
